+        },
+
+        "accent": {
+            "description": "Four semantic accent colors. Drive the update bar, filter validation, status indicators, expert info fallbacks, and the Development Build badge.",
+            "type": "object",
+            "required": ["success", "warning", "error", "info"],
+            "additionalProperties": false,
+            "properties": {
+                "success": { "$ref": "#/$defs/colorPair" },
+                "warning": { "$ref": "#/$defs/colorPair" },
+                "error":   { "$ref": "#/$defs/colorPair" },
+                "info":    { "$ref": "#/$defs/colorPair" }
+            }
