+                "warn":       { "$ref": "#/$defs/colorPair" },
+                "error":      { "$ref": "#/$defs/colorPair" },
+                "foreground": { "$ref": "#/$defs/colorPair" }
+            }
+        },
+
+        "packets": {
+            "description": "Optional packet-display state colors. For each state the unsuffixed key is the row background tint; the matching *Text key is the foreground. `hidden` is text-only (no background) — it dims items rendered on the normal row bg. When a *Text key is omitted, the foreground is derived via contrastingText() against the bg. When `ignored` (bg) is omitted, the row's normal background is used unchanged.",
+            "type": "object",
+            "additionalProperties": false,
+            "properties": {
+                "selection":     { "$ref": "#/$defs/colorPair" },
+                "selectionText": { "$ref": "#/$defs/colorPair" },
