+
+        "conversation": {
+            "description": "Optional Follow Stream conversation colors. `client`/`server` are background tints, `clientText`/`serverText` are foregrounds. When the bg keys are omitted: client = accent.error tint on base; server = brand.primary tint on base. When the *Text keys are omitted: clientText is derived from accent.error (darken in light mode, lighten in dark); serverText is derived from brand.primary the same way.",
+            "type": "object",
+            "additionalProperties": false,
+            "properties": {
+                "client":     { "$ref": "#/$defs/colorPair" },
+                "clientText": { "$ref": "#/$defs/colorPair" },
+                "server":     { "$ref": "#/$defs/colorPair" },
+                "serverText": { "$ref": "#/$defs/colorPair" }
+            }
+        },
+
+        "palette": {
