+            "type": "object",
+            "additionalProperties": false,
+            "properties": {
+                "window":        { "$ref": "#/$defs/colorPair" },
+                "windowText":    { "$ref": "#/$defs/colorPair" },
+                "base":          { "$ref": "#/$defs/colorPair" },
+                "text":          { "$ref": "#/$defs/colorPair" },
+                "alternateBase": { "$ref": "#/$defs/colorPair" },
+                "mid":           { "$ref": "#/$defs/colorPair" },
+                "midlight":      { "$ref": "#/$defs/colorPair" },
+                "accent":        { "$ref": "#/$defs/colorPair" }
+            }
+        },
+
+        "graphs": {
+            "description": "Optional rotating color cycle for I/O graphs, sequence/flow diagrams, TCP stream plots, RTP player, and IAX2 analysis. Custom themes may provide any number of colors; no backfill from the default theme.",
+            "type": "array",
+            "items": { "$ref": "#/$defs/colorPair" }
+        },
+
+        "fonts": {
+            "description": "Optional font hints. User's `gui.fonts.qt.font_name` preference overrides the theme's monospace setting when set.",
+            "type": "object",
