+                "regular":   { "$ref": "#/$defs/fontHint" },
+                "monospace": { "$ref": "#/$defs/fontHint" }
+            }
+        },
+
+        "images": {
+            "description": "Reserved for future use; not currently consumed by ThemeParser.",
+            "type": "object"
+        },
+
+        "syntax": {
+            "description": "Reserved for future use; not currently consumed by ThemeParser.",
+            "type": "object"
+        }
+    },
+
+    "$defs": {
+
+        "colorValue": {
+            "description": "A CSS color string: \"#rrggbb\", \"#rrggbbaa\", or \"rgba(r,g,b,a)\" with alpha 0-255 (QSS convention, NOT 0-1).",
+            "type": "string",
+            "pattern": "^(#[0-9a-fA-F]{6}([0-9a-fA-F]{2})?|rgba\\(\\s*\\d{1,3}\\s*,\\s*\\d{1,3}\\s*,\\s*\\d{1,3}\\s*,\\s*\\d{1,3}\\s*\\))$"
